  /// Return the position `rhs` bytes before `lhs`.
  public static func - (
    lhs: AbsolutePosition,
    rhs: SourceLength
  ) -> AbsolutePosition {
    let utf8Offset = lhs.utf8Offset - rhs.utf8Length
